package com.drogaria.backend.controller;
import com.drogaria.backend.dto.*; import com.drogaria.backend.service.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/agendamento") public class AgendamentoController { private final AgendamentoService s; private final CarrinhoService acesso; public AgendamentoController(AgendamentoService s,CarrinhoService a){this.s=s;acesso=a;} @PostMapping public ResponseEntity<AgendamentoResponse> criar(@Valid @RequestBody AgendamentoRequest r,Authentication a){acesso.validarAcesso(r.getIdCliente(),a);return ResponseEntity.status(HttpStatus.CREATED).body(s.criar(r));} @GetMapping("/{id}") public AgendamentoResponse buscar(@PathVariable Integer id){return s.buscar(id);} @GetMapping("/cliente/{id}") public List<AgendamentoResponse> cliente(@PathVariable Integer id,Authentication a){acesso.validarAcesso(id,a);return s.cliente(id);} @GetMapping("/loja/{id}") public List<AgendamentoResponse> loja(@PathVariable Integer id){return s.loja(id);} @PutMapping("/{id}/cancelar") public ResponseEntity<Void> cancelar(@PathVariable Integer id){s.cancelar(id);return ResponseEntity.noContent().build();} }